// Custom sampler stubs (mapped to noise texture)
#define sampler_lichen sampler_noise_lq
#define sat clamp01
#define GP GetPixel
#define GB1 GetBlur1
#define rp rand_preset
sampler sampler_lichen;
const float quality = 8, depth=.12/quality, k1=48;
vec3 li, licol, screen3;
vec2 dz, uv0, uv1, uv2, uv4, rsl, rsl0, rsl2;
float  r,lprof,noise,gmask,tmp,pa,prad,l,h1,ring;
static float lav_gnd = -1;
vec3 lavcol (float t){t=sat(t * 1.0-0.05); return 2.0 * vec3(t * 1.0,pow(t, 2.0 ),pow(t, 8.0 ));}
//vec3 lavcol (float t) {return sat(t-vec3 (0.07,0.3,0.7))*vec3( 2.0 , 2.0 , 2.0 );}
const vec3 mov = vec3(q29,q30, 0.0 );
const vec3 t   = vec3(q20,q23,q26);
const vec3 s   = vec3(q22,q25,q28);
const vec3 ts  = cross(t,s);
const float myzoom=q31;
const vec2 hor = vec2 ( 1.0 , 0.0 )*(vec2(1.0)/uTexSize);
const vec2 ver = vec2 ( 0.0 , 1.0 )*(vec2(1.0)/uTexSize);
float atan3 (float x,float y)
{float r, a; if (abs(x)>abs(y))
{a=y/x; r=0.973*a-0.191*a*a*a;return (x>0?r:r+M_PI);} else
{a=x/y; r=M_PI / 2.0-0.973*a+0.191*a*a*a;return (y>0?r:r+M_PI);}}
vec2 project (float d)  {float z;
z = d/multiply(ts,screen3); if(z>3) {z=0;}
return (multiply(float2x3(t,s),cross(ts,screen3))*z+mov);}
vec3 get (vec2 uvi, float r) {return mix(GetPixel(uvi), GetBlur1(uvi),r);}
martin
