for (int m=1; m <= quality; m++) {
rsl = fract(project (lav_gnd));
r= sat(length (rsl-0.5));
struc = get(rsl,r*1.5);
lprof = sat (1.0 - mix(struc.b, 0.75, sat(5.5-r*q1))) + 0.0*(struc.r-0.5) / 4.0;
lav_gnd -= clamp01(4.0 * (lprof-m/quality))*depth * (1.0 - r);  }
