dz.x = dot(GP(rsl+hor)-GP(rsl-hor),vec3(-0.2, 0.0 , 1.0 ));
dz.y = dot(GP(rsl+ver)-GP(rsl-ver),vec3(-0.2, 0.0 , 1.0 ));
