ring = ceil(l);
dz *= ring>4;
h1=fract(l);
float rill = (ring<6) * sat (-10+24*abs(fract(l)-0.5));
dz += rill*.15;
// spectrum calc
uv2=rsl-0.5;
float ang1 = atan3(uv2.x,uv2.y)*1.5;
float n=int(k1*ang1/M_PI);
float amp = GB1(vec2(0.015,n/k1)).g*(n>0)*(n<k1);
//licht
tmp=q5*(5.0 - ring);
uv4 = rsl.xy+dz+ dot((rsl-0.5),vec2(sin(tmp+q6),cos(tmp)))-0.5;
licol = (0.2+roam_sin) / 2.0;
li = 0.75*exp(-32*abs(uv4.x))*(GP(rsl).r<0.1)*licol;;
ret = GP(rsl).b*q7*sat(1-2*length(rsl-0.5-dz * 8.0-vec2(q2,q3))) * texture(sampler_lichen,rsl * 4.0);
ret-=rill*.25;
ret -= 8.0 * sat(-dz.x);
ret = sat (ret);
ret += li*(ring<6)*(ring>1)*sat(5.0 - l);
ret += lavcol(GP(rsl).r);
// spectrum draw
float dmask = sat(sin(2.0 * ang1*k1)+0.5);
ret *= !(dmask * (l<3.8)*(l>3.2)*(n>0)*(n<k1));
ret += dmask * (l<3.8)*(l>(4.0 - amp*0.8)) *vec3(0.3,0.6, 2.0 );
ret = sat(ret);
//Particles
uv2=(uv-0.5)*vec2(0.92, 1.0 )+0.5; //linker Rand;
pa = GetPixel(uv2).g;
ret*=sat(1.0 - (pa>0.3));
pa = max(pa, min(0.5,2.0 * GetBlur2(uv2).g));
ret += lavcol(pa*1.5) ;
//####Funken
uv1 = (screen3.xy+0.5-vec2(q9,q10));
ret += 1.0 / length(uv1)*q11*licol;
uv1 = (screen3.xy+0.5+8*GP(rsl).b*dz-vec2(q13,q14));
ret += 1.0 / length(uv1)*q15*licol;
uv4=rsl0-0.5; //backrotation zu aufwendig
uv2=uv4; uv4.x+=uv2.y; uv4.y-=uv2.x;
float r = sat(-0.2-0.75*rp.x-(uv4.x) / 2.0+lprof / 2.0);
ret = mix(ret,  vec3 (.3+r,0.5, 1.0),r);
ret = vec3( 1.0 ) - exp(-ret*1.6);
  fragColor = vec4(ret, 1.0);
}

