vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }
vec4 noise3(vec2 uv) { return texture(sampler_noise_lq, uv); }
vec3 GetMain(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec2 multiply(vec2 v, mat2 m) { return m * v; }
vec3 multiply(vec3 v, mat3 m) { return m * v; }
vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
#define sat clamp01
#define snm sampler_noise_mq
#define rp rand_preset
#define GP GetPixel
const float lf=q17, prog=q8;
const vec2 hor = vec2 ( 1.0 , 0.0 )*(vec2(1.0)/uTexSize);
const vec2 ver = vec2 ( 0.0 , 1.0 )*(vec2(1.0)/uTexSize);
vec2 dz,db,uv1,uv2,mskull;
float ring, tmp, k1;
vec3 noi (vec2 uvi, float t) {float q, r=.1; t+= rp+uTime*0.0004;
for (float i=0; i<6; i++) {q=pow(2,i); r+=texture(snm, uvi*q+t)/q;} return r;}
vec2 skull (vec2 uvi)
{ float tmp=0; float br=uvi.x*uvi.y<0;
uvi=multiply(uvi,mat2(0.7,0.7,-0.7,0.7));
uvi = mix(uvi,uvi.yx,(abs(uvi.y)<abs(uvi.x)));
vec2 uvo=uvi;
uvi.y=.35-abs(uvi.y);
uvi=vec2(6.0 * pow(uvi.x,1.6),uvi.y)*3.5;
vec2 r= pow(uvi-0.055-uvi.x*.2,1.4);
float e = length(2.0 * r)-0.055;
float eyes= sat(1-256*pow(e, 2.0 ));
eyes *= sat( 1.0 - uvi.x*1.8);
float nose = sat(length ((uvi-vec2( 0.0 ,0.15))*vec2(12.0 / uvi.y, 15.0 )));
float mouth = sat(1-6*length(uvi.x))*(1-0.2*texture(snm,uvo.x * 4.0)*sat(16.0 * uvi.y-3.9));
eyes = max(eyes,mouth*(uvi.y>0.15)*sat(8.0 - uvi.y * 23.0))*nose;
tmp = max(eyes,(1.05-3.2*length(uvi))*(uvi.y<uvi.x*.2-0.02))*0.9;
return vec2(.001/length(r)*br,tmp)*(1.0 - prog);
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec3 h = GP(uv+hor) - GP(uv-hor);
vec3 v = GP(uv+ver) - GP(uv-ver);
dz = vec2(h.r,v.r);
db = vec2(h.b,v.b);
uv1 = (uv-0.5);
float l = length(uv1*q1);
ring = ceil(l);
uv1 += (noi(uv / 2.0, 0.0 ) - 1.0)*prog*0.2;
mskull=skull(uv1);
ret.b = 0.7+(noi(uv1 / 5.0, 0.0 ).r*.5-0.3-0.09*l);
ret.b = sat(max(ret.b,mskull.y*0.9)) ;
vec2 noise = texture(sampler_noise_lq,uv * 4.0+rand_frame)-0.5;
uv2= uv * 0.0+0.1*noi(uv / 4.0, 0.0 );
ret.r = abs(noi(uv2 / 2.0+noise*(vec2(1.0)/uTexSize) * 4.0*lf, 0.0 ) - 1.0)*(2.0 - rad) ;
ret.r *= sat(texture(sampler_noise_hq,uv / 2.0+uTime*0.0034)) * 2.0*(1.3-rad);
ret.r = mix(ret.r, GetPixel(uv-dz*(vec2(1.0)/uTexSize) * 4.0).r,0.95);
float dit = sat(0.004/length (rp.y*.5+0.3-uv.y-0.14*noi(uv / 8.0, 0.0 )))*0.25*(ring>4);
ret.r += dit;
ret.b-=dit*0.25;
ret.r += rp.x*(sat (3.3*noi(0.5*ang+uv2+db*rp.z, 0.0 ) - 4.0))*sat(1-1.6*ret.b)*(ret.b+0.1);
ret.r *= sat(1.0 - GetBlur1(uv).b*0.5) * sat(rad*1.5);
ret.r += exp(-8*l/q17*(1.0 - prog));
ret.r+=mskull.x * 2.0*sat(audioMidSmooth-0.5);
vec2 nn=texture(sampler_noise_lq,uv * 8.0+rand_frame)-0.5;
ret.g = max(ret.g,GetPixel(uv+nn*0.01).g*0.4);
ret.r += (0.01/abs(noi(uv*.2,rand_frame / 8.0+uTime / 8.0)-0.5))*mskull.y*sin(q16 / 2.0-ang)*audioMidSmooth*sat(q17-3.5);
ret.b-=.03*ret.r;
ret.rb *= sat (2.0 - rad*1.3);
ret-=0.004;
  fragColor = vec4(ret, 1.0);
}

