ret.r *= sat(1-GetBlur1(uv).b*0.5) * sat(rad*1.5);
ret.r += exp(-8*l/q17*(1-prog));
ret.r+=mskull.x*2*sat(mid_att-0.5);
float2 nn=tex2D(sampler_noise_lq,uv*8+rand_frame)-0.5;
ret.g = max(ret.g,GetPixel(uv+nn*0.01).g*0.4);
ret.r += (0.01/abs(noi(uv*.2,rand_frame/8+time/8)-0.5))*mskull.y*sin(q16/2-ang)*mid_att*sat(q17-3.5);
ret.b-=.03*ret.r;
ret.rb *= sat (2-rad*1.3);
ret-=0.004;
}

