#define sat saturate
#define GP GetPixel
#define GB1 GetBlur1
#define rp rand_preset
sampler sampler_lichen;
static const float quality = 8, depth=.12/quality, k1=48;
float3 li, licol, screen3;
float2 dz, uv0, uv1, uv2, uv4, rsl, rsl0, rsl2;
float  r,lprof,noise,gmask,tmp,pa,prad,l,h1,ring;
static float lav_gnd = -1;
float3 lavcol (float t){t=sat(t*1-0.05); return 2*float3(t*1,pow(t,2),pow(t,8));}
//float3 lavcol (float t) {return sat(t-float3 (0.07,0.3,0.7))*float3(2,2,2);}
static const float3 mov = float3(q29,q30,0);
static const float3 t   = float3(q20,q23,q26);
static const float3 s   = float3(q22,q25,q28);
static const float3 ts  = cross(t,s);
static const float myzoom=q31;
static const float2 hor = float2 (1,0)*texsize.zw;
static const float2 ver = float2 (0,1)*texsize.zw;
float atan3 (float x,float y)
{float r, a; if (abs(x)>abs(y))
{a=y/x; r=0.973*a-0.191*a*a*a;return (x>0?r:r+M_PI);} else
{a=x/y; r=M_PI/2-0.973*a+0.191*a*a*a;return (y>0?r:r+M_PI);}}
float2 project (float d)  {float z;
z = d/mul(ts,screen3); if(z>3) {z=0;}
return (mul(float2x3(t,s),cross(ts,screen3))*z+mov);}
float3 get (float2 uvi, float r) {return lerp (GetPixel(uvi), GetBlur1(uvi),r);}
martin
END
shader_body {
screen3 = float3 ((uv-0.5)*aspect.xy,myzoom);
rsl0 = project (lav_gnd); float3 struc;
for (int m=1; m <= quality; m++) {
rsl = frac(project (lav_gnd));
r= sat(length (rsl-0.5));
struc = get(rsl,r*1.5);
lprof = sat (1-lerp (struc.b, 0.75, sat(5.5-r*q1)))+0*(struc.r-0.5)/4;
lav_gnd -= saturate(4*(lprof-m/quality))*depth * (1-r);  }
rsl = project(lav_gnd);
dz.x = dot(GP(rsl+hor)-GP(rsl-hor),float3(-0.2,0,1));
dz.y = dot(GP(rsl+ver)-GP(rsl-ver),float3(-0.2,0,1));
l = length(rsl-0.5)*q1;
ring = ceil(l);
dz *= ring>4;
h1=frac(l);
float rill = (ring<6) * sat (-10+24*abs(frac(l)-0.5));
dz += rill*.15;
// spectrum calc
uv2=rsl-0.5;
float ang1 = atan3(uv2.x,uv2.y)*1.5;
float n=int(k1*ang1/M_PI);
float amp = GB1(float2(0.015,n/k1)).g*(n>0)*(n<k1);
//licht
tmp=q5*(5-ring);
uv4 = rsl.xy+dz+ dot((rsl-0.5),float2(sin(tmp+q6),cos(tmp)))-0.5;
licol = (0.2+roam_sin)/2;
li = 0.75*exp(-32*abs(uv4.x))*(GP(rsl).r<0.1)*licol;;
ret = GP(rsl).b*q7*sat(1-2*length(rsl-0.5-dz*8-float2(q2,q3))) * tex2D(sampler_lichen,rsl*4);
ret-=rill*.25;
ret -= 8*sat(-dz.x);
ret = sat (ret);
ret += li*(ring<6)*(ring>1)*sat(5-l);
ret += lavcol(GP(rsl).r);
// spectrum draw
float dmask = sat(sin(2*ang1*k1)+0.5);
ret *= !(dmask * (l<3.8)*(l>3.2)*(n>0)*(n<k1));
ret += dmask * (l<3.8)*(l>(4-amp*0.8)) *float3(0.3,0.6,2);
ret = sat(ret);
//Particles
uv2=(uv-0.5)*float2(0.92,1)+0.5; //linker Rand;
pa = GetPixel(uv2).g;
ret*=sat(1-(pa>0.3));
pa = max(pa, min(0.5,2*GetBlur2(uv2).g));
ret += lavcol(pa*1.5) ;
//####Funken
uv1 = (screen3.xy+0.5-float2(q9,q10));
ret += 1/length(uv1)*q11*licol;
uv1 = (screen3.xy+0.5+8*GP(rsl).b*dz-float2(q13,q14));
ret += 1/length(uv1)*q15*licol;
uv4=rsl0-0.5; //backrotation zu aufwendig
uv2=uv4; uv4.x+=uv2.y; uv4.y-=uv2.x;
float r = sat(-0.2-0.75*rp.x-(uv4.x)/2+lprof/2);
ret = lerp (ret,  float3 (.3+r,0.5,1),r);
ret = 1-exp(-ret*1.6);
}

